import { connect, mapProps } from '@formily/react';
import { Switch as ArcoSwitch } from '@arco-design/web-react';

export const Switch = connect(
  ArcoSwitch,
  mapProps(
    {
      value: 'checked',
      loading: true,
    },
    props => {
      const { onChange } = props;
      // delete props.value;
      return {
        ...props,
        onChange(checked) {
          onChange?.(checked, null);
        },
      };
    }
  )
);

export default Switch;
